import logging
from taf.internal.managedobject import ManagedObject
from taf.sw.qualcomm.license.executor import (LKCRunningChecker, SSHTCPIPChannelProvider,
                                              LicenseKeeperShell, ManagedSshConnectionEx)
from taf.sw.qualcomm.license.exception import LoginFailed, LogoutFailed, GetLicenceFailed, ReleaseLicenceFailed


class LicenseKeeperClient(ManagedObject):
    """
    License Keeper client class, provides basic methods to operate License Keeper server.
    """
    _LOGIN = 'login {} {}'
    _LOGOUT = 'logout'
    _GET_LICENCE_QXDM_5G = 'keep QXDM 5G'
    _GET_LICENCE_QXDM_4G = 'keep QXDM 4G'
    _GET_LICENCE_QCAT_5G = 'keep QCAT 5G'
    _GET_LICENCE_QCAT_4G = 'keep QCAT 4G'
    _GET_LICENCE_PCAT_5G = 'keep PCAT 5G'
    _RELEASE_LICENCE_QXDM_5G = 'drop QXDM 5G'
    _RELEASE_LICENCE_QXDM_4G = 'drop QXDM 4G'
    _RELEASE_LICENCE_QCAT_5G = 'drop QCAT 5G'
    _RELEASE_LICENCE_QCAT_4G = 'drop QCAT 4G'
    _RELEASE_LICENCE_PCAT_5G = 'drop PCAT 5G'
    _STATUS_LOGIN_SUCCESS = 'Login success'
    _STATUS_LOGIN_ALREADY = 'User already logged in'
    _STATUS_NOT_LOGIN = 'You are not logged in'
    _STATUS_LOGOUT_SUCCESS = 'Logout success'
    _STATUS_LOGOUT_ALREADY = 'User already logged out'
    _STATUS_GET_LICENCE_SUCCESS = 'Got licence'
    _STATUS_RELEASE_LICENCE_SUCCESS = 'Released Licence successfully'

    def __init__(self, launcher_config, port=None, timeout=None):
        super(LicenseKeeperClient, self).__init__()

        self._path = launcher_config.get('path')
        if not self._path:
            raise ValueError('"path" attribute in launcher configuration is required')

        self._host = launcher_config['host']
        self._user = launcher_config['user']
        self._password = launcher_config['password']
        self._executor_port = launcher_config.get('port', 22)
        self._service_port = port or 6006
        self._timeout = timeout or 10

        self._ssh_runner = ManagedSshConnectionEx(
            self._host,
            self._user,
            self._password,
            self._executor_port)
        self.add_prerequisite(self._ssh_runner)

        # deprecated the legacy class 'Launcher', use 'LKCRunningChecker' in 1.1.0 and higher version
        self._lkc_running_checker = LKCRunningChecker(self._ssh_runner)
        self.add_prerequisite(self._lkc_running_checker)

        self._channel_provider = SSHTCPIPChannelProvider(
            ssh_runner=self._ssh_runner,
            port=self._service_port)

        self._shell = LicenseKeeperShell(channel_provider=self._channel_provider, timeout=self._timeout)
        self.add_prerequisite(self._shell)

    def execute_command(self, command, timeout):
        """
        Execute License Keeper RPI command.

        :param command: str, RPI command
        :param timeout: int
        :return: response of RPI command
        """
        return self._shell.execute(command, timeout)

    def login(self, username, password, timeout=30):
        """
        login the Licence Keeper server via license keeper client.

        :param username: str, Username that Licence Keeper account.
        :param password: str, Password that Licence Keeper account.
        :param timeout: int, default 30 seconds.
        :return:
        """
        command = self._LOGIN.format(username, password)
        command_result = self.execute_command(command, timeout)
        if self._STATUS_LOGIN_SUCCESS in command_result or self._STATUS_LOGIN_ALREADY in command_result:
            logging.info('Login successfully.')
        else:
            raise LoginFailed(command_result)

    def logout(self, timeout=30):
        """
        logout the Licence Keeper server via license keeper client.

        :param timeout: int, default 30 seconds.
        :return:
        """
        command = self._LOGOUT
        command_result = self.execute_command(command, timeout)
        if self._STATUS_LOGOUT_SUCCESS in command_result or self._STATUS_LOGOUT_ALREADY in command_result:
            logging.info('Logout successfully.')
        else:
            raise LogoutFailed(command_result)

    def _get_licence_and_check(self, command, timeout, retry):
        command_result = ''
        self._shell.read_output(timeout=timeout)
        while retry:
            command_result = self.execute_command(command, timeout)
            if self._check_if_get_licence(command, command_result):
                return
            retry = retry - 1
        raise GetLicenceFailed(command_result)

    def _release_licence_and_check(self, command, timeout, retry):
        command_result = ''
        self._shell.read_output(timeout=timeout)
        while retry:
            command_result = self.execute_command(command, timeout)
            if self._check_if_release_licence(command, command_result):
                return
            retry = retry - 1
        raise ReleaseLicenceFailed(command_result)

    def _check_if_login(self, result):
        if self._STATUS_NOT_LOGIN in result:
            raise LoginFailed(result)

    def _check_if_get_licence(self, command, result):
        self._check_if_login(result)
        return command in result and self._STATUS_GET_LICENCE_SUCCESS in result

    def _check_if_release_licence(self, command, result):
        return command in result and self._STATUS_RELEASE_LICENCE_SUCCESS in result

    def get_licence_qxdm_5g(self, timeout=30, retry=3):
        """
        get QXDM 5G licence from the Licence Keeper server.
        :param timeout: int, default 30 seconds.
        :param retry: int, default 3.
        :return:
        """
        return self._get_licence_and_check(self._GET_LICENCE_QXDM_5G, timeout, retry)

    def get_licence_qxdm_4g(self, timeout=30, retry=3):
        """
        get QXDM 4G licence from the Licence Keeper server.
        :param timeout: int, default 30 seconds.
        :param retry: int, default 3.
        :return:
        """
        return self._get_licence_and_check(self._GET_LICENCE_QXDM_4G, timeout, retry)

    def get_licence_qcat_5g(self, timeout=30, retry=3):
        """
        get QCAT 5G licence from the Licence Keeper server.
        :param timeout: int, default 30 seconds.
        :param retry: int, default 3.
        :return:
        """
        return self._get_licence_and_check(self._GET_LICENCE_QCAT_5G, timeout, retry)

    def get_licence_qcat_4g(self, timeout=30, retry=3):
        """
        get QCAT 4G licence from the Licence Keeper server.
        :param timeout: int, default 30 seconds.
        :param retry: int, default 3.
        :return:
        """
        return self._get_licence_and_check(self._GET_LICENCE_QCAT_4G, timeout, retry)

    def get_licence_pcat_5g(self, timeout=30, retry=3):
        """
        get PCAT 5G licence from the Licence Keeper server.
        :param timeout: int, default 30 seconds.
        :param retry: int, default 3.
        :return:
        """
        return self._get_licence_and_check(self._GET_LICENCE_PCAT_5G, timeout, retry)

    def release_licence_qxdm_5g(self, timeout=30, retry=3):
        """
        release QXDM 5G licence from the Licence Keeper server.
        :param timeout: int, default 30 seconds.
        :param retry: int, default 3.
        :return:
        """
        return self._release_licence_and_check(self._RELEASE_LICENCE_QXDM_5G, timeout, retry)

    def release_licence_qxdm_4g(self, timeout=30, retry=3):
        """
        release QXDM 4G licence from the Licence Keeper server.
        :param timeout: int, default 30 seconds.
        :param retry: int, default 3.
        :return:
        """
        return self._release_licence_and_check(self._RELEASE_LICENCE_QXDM_4G, timeout, retry)

    def release_licence_qcat_5g(self, timeout=30, retry=3):
        """
        release QCAT 5G licence from the Licence Keeper server.
        :param timeout: int, default 30 seconds.
        :param retry: int, default 3.
        :return:
        """
        return self._release_licence_and_check(self._RELEASE_LICENCE_QCAT_5G, timeout, retry)

    def release_licence_qcat_4g(self, timeout=30, retry=3):
        """
        release QCAT 4G licence from the Licence Keeper server.
        :param timeout: int, default 30 seconds.
        :param retry: int, default 3.
        :return:
        """
        return self._release_licence_and_check(self._RELEASE_LICENCE_QCAT_4G, timeout, retry)

    def release_licence_pcat_5g(self, timeout=30, retry=3):
        """
        release PCAT 5G licence from the Licence Keeper server.
        :param timeout: int, default 30 seconds.
        :param retry: int, default 3.
        :return:
        """
        return self._release_licence_and_check(self._RELEASE_LICENCE_PCAT_5G, timeout, retry)
